import { test, expect } from '@playwright/test';

const BASE_URL = process.env.TARGET_URL || 'https://www.saucedemo.com';

test('Complete purchase flow', async ({ page }) => {
  // Navigate to base URL (assumes authenticated session via storage state or prior login)
  console.log('[Timeline] Navigate to base URL');
  await page.goto(BASE_URL);

  // Step 1: Sort products by Name (A to Z) and verify sorting order
  console.log('[Timeline] Sort products by Name (A to Z)');
  await page.locator('[data-test="product_sort_container"]').selectOption({ label: 'Name (A to Z)' });
  const productNamesAZ = await page.locator('.inventory_item_name').allTextContents();
  const sortedNamesAZ = [...productNamesAZ].sort((a, b) => a.localeCompare(b));
  await expect(productNamesAZ).toEqual(sortedNamesAZ);

  // Step 2: Sort products by Price (low to high) and verify sorting order
  console.log('[Timeline] Sort products by Price (low to high)');
  await page.locator('[data-test="product_sort_container"]').selectOption({ label: 'Price (low to high)' });
  const priceElements = await page.locator('.inventory_item_price').allTextContents();
  const prices = priceElements.map(p => parseFloat(p.replace('$', '')));
  const sortedPrices = [...prices].sort((a, b) => a - b);
  await expect(prices).toEqual(sortedPrices);

  // Step 3: Add two different products to the cart
  const product1 = 'Sauce Labs Backpack';
  const product2 = 'Sauce Labs Bolt T-Shirt';
  console.log('[Timeline] Add first product to cart');
  await page.locator(`[data-test="add-to-cart-${product1.toLowerCase().replace(/ /g, '-')}"]`).click();
  console.log('[Timeline] Add second product to cart');
  await page.locator(`[data-test="add-to-cart-${product2.toLowerCase().replace(/ /g, '-')}"]`).click();

  // Step 4: Verify the cart badge shows a count of 2
  console.log('[Timeline] Verify cart badge count');
  await expect(page.locator('.shopping_cart_badge')).toHaveText('2');

  // Step 5: Navigate to the Cart page and verify both products appear with correct names, descriptions, quantities, and prices
  console.log('[Timeline] Navigate to Cart page');
  await page.locator('.shopping_cart_link').click();
  await expect(page).toHaveURL(/.*cart\.html/);
  const cartItems = page.locator('.cart_item');
  await expect(cartItems).toHaveCount(2);
  // Verify first product
  await expect(cartItems.nth(0).locator('.inventory_item_name')).toHaveText(product1);
  await expect(cartItems.nth(0).locator('.inventory_item_desc')).toBeVisible();
  await expect(cartItems.nth(0).locator('.cart_quantity')).toHaveText('1');
  await expect(cartItems.nth(0).locator('.inventory_item_price')).toBeVisible();
  // Verify second product
  await expect(cartItems.nth(1).locator('.inventory_item_name')).toHaveText(product2);
  await expect(cartItems.nth(1).locator('.inventory_item_desc')).toBeVisible();
  await expect(cartItems.nth(1).locator('.cart_quantity')).toHaveText('1');
  await expect(cartItems.nth(1).locator('.inventory_item_price')).toBeVisible();

  // Step 6: Remove one product from the cart and verify cart updates
  console.log('[Timeline] Remove one product from cart');
  await page.locator(`[data-test="remove-${product1.toLowerCase().replace(/ /g, '-')}"]`).click();
  await expect(page.locator('.shopping_cart_badge')).toHaveText('1');
  await expect(page.locator('.cart_item')).toHaveCount(1);
  await expect(page.locator('.cart_item .inventory_item_name')).toHaveText(product2);

  // Step 7: Click Continue Shopping and verify return to Products page
  console.log('[Timeline] Click Continue Shopping');
  await page.locator('[data-test="continue-shopping"]').click();
  await expect(page).toHaveURL(/.*inventory\.html/);

  // Step 8: Navigate back to Cart and proceed to Checkout
  console.log('[Timeline] Navigate back to Cart');
  await page.locator('.shopping_cart_link').click();
  await expect(page).toHaveURL(/.*cart\.html/);
  console.log('[Timeline] Proceed to Checkout');
  await page.locator('[data-test="checkout"]').click();
  await expect(page).toHaveURL(/.*checkout-step-one\.html/);

  // Step 9: Enter valid First Name, Last Name, and Zip/Postal Code on the Information page
  console.log('[Timeline] Fill checkout information');
  await page.locator('[data-test="firstName"]').fill('John');
  await page.locator('[data-test="lastName"]').fill('Doe');
  await page.locator('[data-test="postalCode"]').fill('12345');

  // Step 10: Click Continue to proceed to Overview page
  console.log('[Timeline] Click Continue to Overview');
  await page.locator('[data-test="continue"]').click();
  await expect(page).toHaveURL(/.*checkout-step-two\.html/);

  // Step 11: Verify product details, item total, tax, and final total calculation on Overview page
  console.log('[Timeline] Verify overview page details');
  await expect(page.locator('.cart_item')).toHaveCount(1);
  await expect(page.locator('.cart_item .inventory_item_name')).toHaveText(product2);
  const itemPriceText = await page.locator('.cart_item .inventory_item_price').textContent();
  const itemPrice = parseFloat(itemPriceText!.replace('$', ''));
  const itemTotalText = await page.locator('.summary_subtotal_label').textContent();
  const itemTotal = parseFloat(itemTotalText!.replace('Item total: $', ''));
  await expect(itemTotal).toBeCloseTo(itemPrice);
  const taxText = await page.locator('.summary_tax_label').textContent();
  const tax = parseFloat(taxText!.replace('Tax: $', ''));
  const totalText = await page.locator('.summary_total_label').textContent();
  const total = parseFloat(totalText!.replace('Total: $', ''));
  await expect(total).toBeCloseTo(itemTotal + tax);

  // Step 12: Click Finish to complete the order
  console.log('[Timeline] Click Finish');
  await page.locator('[data-test="finish"]').click();
  await expect(page).toHaveURL(/.*checkout-complete\.html/);

  // Step 13: Verify order confirmation message and completion image on Checkout Complete page
  console.log('[Timeline] Verify order confirmation');
  await expect(page.locator('.complete-header')).toHaveText('Thank you for your order!');
  await expect(page.locator('.pony_express')).toBeVisible();

  // Step 14: Click Back Home and verify navigation returns to Products page with empty cart
  console.log('[Timeline] Click Back Home');
  await page.locator('[data-test="back-to-products"]').click();
  await expect(page).toHaveURL(/.*inventory\.html/);
  await expect(page.locator('.shopping_cart_badge')).toHaveCount(0);
});
